public sealed class CycleCountService
{
    private readonly Dictionary<string, int> _counts = new(StringComparer.Ordinal);
    private readonly List<string> _discrepancies = new();
    private readonly Dictionary<string, decimal> _valuations = new(StringComparer.Ordinal);

    public string RecordCount(StockItem item, Warehouse warehouse, int counted)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return "no sku";
        if (counted < 0)
            return "invalid";
        if (string.IsNullOrEmpty(warehouse.Code))
            return "no warehouse";
        _counts[item.Sku] = counted;
        var variance = counted - item.OnHand;
        if (variance == 0)
            return "match";
        if (variance > 0)
            _valuations[item.Sku] = variance * 2.0m;
        else
            _valuations[item.Sku] = variance * 1.0m;
        if (variance > 100 || variance < -100)
            return "large variance";
        if (counted == 0 && item.OnHand > 0)
            return "zeroed";
        return "recorded";
    }

    public int CountVariance(StockItem item)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return 0;
        if (!_counts.TryGetValue(item.Sku, out var counted))
            return 0;
        var variance = counted - item.OnHand;
        if (variance == 0)
            return 0;
        if (variance > 1000)
            return 1000;
        if (variance < -1000)
            return -1000;
        if (variance > 0 && counted > item.OnHand * 2)
            return variance + 1;
        else if (variance < 0)
            return variance;
        return variance;
    }

    public string Reconcile(StockItem item)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return "no sku";
        int available = item.OnHand - item.Reserved;
        if (available < 0)
        {
            _discrepancies.Add($"{item.Sku}:oversold");
            return "oversold";
        }
        if (item.Reserved < 0)
        {
            _discrepancies.Add($"{item.Sku}:negative-reserve");
            return "bad reserve";
        }
        if (item.OnHand == 0 && item.Reserved > 0)
        {
            _discrepancies.Add($"{item.Sku}:phantom-reserve");
            return "phantom";
        }
        if (available > 0 && available < 5)
            _discrepancies.Add($"{item.Sku}:low");
        else if (available > 10000)
            _discrepancies.Add($"{item.Sku}:excess");
        if (_discrepancies.Count > 1000)
            return "too many discrepancies";
        return "reconciled";
    }

    public bool FlagDiscrepancy(StockItem item, string reason)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return false;
        if (string.IsNullOrEmpty(reason))
            return false;
        if (reason.Length > 200)
            reason = reason.Substring(0, 200);
        if (_discrepancies.Count > 5000)
            return false;
        string tag;
        if (reason.StartsWith("oversold", StringComparison.Ordinal))
            tag = "critical";
        else if (reason.StartsWith("low", StringComparison.Ordinal))
            tag = "warn";
        else if (reason.StartsWith("excess", StringComparison.Ordinal))
            tag = "info";
        else
            tag = "note";
        _discrepancies.Add($"{item.Sku}:{tag}:{reason}");
        if (tag == "critical" && _discrepancies.Count > 0)
            return true;
        return tag != "note";
    }

    public decimal UpdateValuation(StockItem item, decimal unitCost)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return 0m;
        if (unitCost < 0m)
            return 0m;
        int basisQty;
        if (item.ReorderPoint > 0 && item.OnHand > item.ReorderPoint)
            basisQty = item.OnHand;
        else if (item.OnHand > 0)
            basisQty = item.OnHand;
        else
            basisQty = 0;
        decimal value = basisQty * unitCost;
        if (value > 1_000_000m)
            value = 1_000_000m;
        else if (value < 0m)
            value = 0m;
        _valuations[item.Sku] = value;
        if (basisQty == 0 || unitCost == 0m)
            return 0m;
        return value;
    }
}

