        var variance = counted - item.OnHand;
        if (variance == 0)
            return 0;
        if (variance > 1000)
            return 1000;
        if (variance < -1000)
            return -1000;
        if (variance > 0 && counted > item.OnHand * 2)
            return variance + 1;
        else if (variance < 0)
            return variance;
        return variance;
    }

